import{_ as e,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse(`{"title":"HTML5 History 模式","description":"在创建路由器实例时，history 配置允许我们在不同的历史模式中进行选择。 Hash 模式 hash 模式是用 createWebHashHistory() 创建的： import \\\\{ createRouter, createWebHashHistory \\\\} from 'v。","frontmatter":{"title":"HTML5 History 模式","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"在创建路由器实例时，history 配置允许我们在不同的历史模式中进行选择。 Hash 模式 hash 模式是用 createWebHashHistory() 创建的： import \\\\{ createRouter, createWebHashHistory \\\\} from 'v。","sidebarWeight":7,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/HTML5 History 模式.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/HTML5 History 模式.md","filePath":"posts/Vue系统教程/04-路由与状态管理/HTML5 History 模式.md"}`),i={name:"posts/Vue系统教程/04-路由与状态管理/HTML5 History 模式.md"};function u(a,t,n,l,c,p){return o(),r("div",null,[...t[0]||(t[0]=[s('<div><h1 id="html5-history-模式" tabindex="-1">HTML5 History 模式 <a class="header-anchor" href="#html5-history-模式" aria-label="Permalink to &quot;HTML5 History 模式&quot;">​</a></h1><blockquote><p>本节目标：理解“HTML5 History 模式”的核心思路，并能把它用于实际开发或面试表达。 在创建路由器实例时，history 配置允许我们在不同的历史模式中进行选择。</p></blockquote><p><strong>Hash</strong> <strong>模式</strong> hash 模式是用 createWebHashHistory() 创建的： import { createRouter, createWebHashHistory } from &#39;vue-router&#39; const router = createRouter({ history: createWebHashHistory(), routes: [ //... ], }) 它在内部传递的实际 URL 之前使用了一个哈希字符（#）。由于这部分 URL 从未被发送到服务器，所以它不需要在服务器层面上进行任何特殊处理。不过，它在 SEO 中确实有不好的影响。如果你担心这个问题，可以使用 HTML5 模式。</p><p><strong>HTML5</strong> <strong>模式</strong> 用 createWebHistory() 创建 HTML5 模式，推荐使用这个模式： js import { createRouter, createWebHistory } from &#39;vue-router&#39; const router = createRouter({ history: createWebHistory(), routes: [ //... ], }) 当使用这种历史模式时，URL 会看起来很 &quot;正常&quot;，例如 <a href="https://example.com/user/id%E3%80%82%E6%BC%82%E4%BA%AE" target="_blank" rel="noreferrer">https://example.com/user/id</a>。漂亮!</p><p>不过，问题来了。由于我们的应用是一个单页的客户端应用，如果没有适当的服务器配置，用户在浏览器中直接访问 <a href="https://example.com/user/id%EF%BC%8C%E5%B0%B1%E4%BC%9A%E5%BE%97%E5%88%B0%E4%B8%80%E4%B8%AA" target="_blank" rel="noreferrer">https://example.com/user/id</a>，就会得到一个 404 错误。这就尴尬了。</p><p>不用担心：要解决这个问题，你需要做的就是在你的服务器上添加一个简单的回退路由。如果 URL 不匹配任何静态资源，它应提供与你的应用程序中的 index.html 相同的页面。漂亮依旧!</p><p><strong>服务器配置示例</strong> 注意：以下示例假定你正在从根目录提供服务。如果你部署到子目录，你应该使用Vue CLI 的 publicPath 配置和相关的路由器的 base 属性。你还需要调整下面的例子，以使用子目录而不是根目录（例如，将RewriteBase/ 替换为 RewriteBase/name-of-your-subfolder/）。</p><p>Apache &lt;IfModule mod_negotiation.c&gt; Options -MultiViews &lt;/IfModule&gt; &lt;IfModule mod_rewrite.c&gt; RewriteEngine On RewriteBase / RewriteRule ^index.html$ - [L] RewriteCond %{REQUEST_FILENAME} !-f RewriteCond %{REQUEST_FILENAME} !-d RewriteRule . /index.html [L] &lt;/IfModule&gt; 也可以使用 FallbackResource 代替 mod_rewrite。</p><p>nginx location / { try_files $uri $uri/ /index.html; }</p><p>原生 Node.js const http = require(&#39;http&#39;) const fs = require(&#39;fs&#39;) const httpPort = 80 http .createServer((req, res) =&gt; { fs.readFile(&#39;index.html&#39;, &#39;utf-8&#39;, (err, content) =&gt; { if (err) { console.log(&#39;We cannot open &quot;index.html&quot; file.&#39;) } res.writeHead(200, { &#39;Content-Type&#39;: &#39;text/html; charset=utf-8&#39;, }) res.end(content) }) }) .listen(httpPort, () =&gt; { console.log(&#39;Server listening on: <a href="http://localhost" target="_blank" rel="noreferrer">http://localhost</a>:%s&#39;, httpPort) })</p><p><strong>Express + Node.js</strong> 对于 Node.js/Express，可以考虑使用 connect-history-api-fallback 中间件。 Internet Information Services (IIS) 安装 IIS UrlRewrite 在网站的根目录下创建一个 web.config 文件，内容如下： xml &lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;configuration&gt; &lt;system.webServer&gt; &lt;rewrite&gt; &lt;rules&gt; &lt;rule name=&quot;Handle History Mode and custom 404/500&quot; stopProcessing=&quot;true&quot;&gt; &lt;match url=&quot;(.<em>)&quot; /&gt; &lt;conditions logicalGrouping=&quot;MatchAll&quot;&gt; &lt;add input=&quot;{REQUEST_FILENAME}&quot; matchType=&quot;IsFile&quot; negate=&quot;true&quot; /&gt; &lt;add input=&quot;{REQUEST_FILENAME}&quot; matchType=&quot;IsDirectory&quot; negate=&quot;true&quot; /&gt; &lt;/conditions&gt; &lt;action type=&quot;Rewrite&quot; url=&quot;/&quot; /&gt; &lt;/rule&gt; &lt;/rules&gt; &lt;/rewrite&gt; &lt;/system.webServer&gt; &lt;/configuration&gt; Caddy v2 try_files {path} / Caddy v1 rewrite { regexp .</em> to {path} / } Firebase hosting 将此添加到你的 firebase.json 中： json { &quot;hosting&quot;: { &quot;public&quot;: &quot;dist&quot;, &quot;rewrites&quot;: [ { &quot;source&quot;: &quot;**&quot;, &quot;destination&quot;: &quot;/index.html&quot; } ] } } Netlify 创建一个 _redirects 文件，包含在你的部署文件中：</p><p>/* /index.html 200 在 vue-cli、nuxt 和 vite 项目中，这个文件通常放在名为 static 或 public 的目录下。 你可以在 Netlify 文档中找到更多关于语法的信息。你也可以创建一个 netlify.toml 来结合其他 Netlify 功能的重定向。 Vercel 在项目根目录创建一个vercel.json文件，内容如下： json { &quot;rewrites&quot;: [{ &quot;source&quot;: &quot;/:path*&quot;, &quot;destination&quot;: &quot;/index.html&quot; }] } Caveat 这有一个注意事项。你的服务器将不再报告 404 错误，因为现在所有未找到的路径都会显示你的 index.html 文件。为了解决这个问题，你应该在你的 Vue 应用程序中实现一个万能的路由来显示 404 页面。 js const router = createRouter({ history: createWebHistory(), routes: [{ path: &#39;/:pathMatch(.*)&#39;, component: NotFoundComponent }], }) 另外，如果你使用的是 Node.js 服务器，你可以通过在服务器端使用路由器来匹配传入的 URL，如果没有匹配到路由，则用 404 来响应，从而实现回退。查看 Vue 服务器端渲染文档了解更多信息。</p></div>',1)])])}const q=e(i,[["render",u]]);export{d as __pageData,q as default};
